def radix_sort_descending(arr: list[int]) -> list[int]:
    if len(arr) <= 1:
        return arr
    positives = [x for x in arr if x >= 0]
    negatives = [-x for x in arr if x < 0]

    def lsd_sort_desc(a: list[int]) -> list[int]:
        if not a:
            return a
        max_val = max(a)
        exp = 1
        while max_val // exp > 0:
            count = [0] * 10
            out = [0] * len(a)
            for x in a:
                count[(x // exp) % 10] += 1
            for i in range(8, -1, -1):
                count[i] += count[i + 1]
            for i in range(len(a) - 1, -1, -1):
                d = (a[i] // exp) % 10
                out[count[d] - 1] = a[i]
                count[d] -= 1
            a = out
            exp *= 10
        return a

    def lsd_sort_asc(a: list[int]) -> list[int]:
        if not a:
            return a
        max_val = max(a)
        exp = 1
        while max_val // exp > 0:
            count = [0] * 10
            out = [0] * len(a)
            for x in a:
                count[(x // exp) % 10] += 1
            for i in range(1, 10):
                count[i] += count[i - 1]
            for i in range(len(a) - 1, -1, -1):
                d = (a[i] // exp) % 10
                out[count[d] - 1] = a[i]
                count[d] -= 1
            a = out
            exp *= 10
        return a

    sorted_pos = lsd_sort_desc(positives)
    sorted_neg = lsd_sort_asc(negatives)
    return sorted_pos + [-x for x in sorted_neg]

